if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    RequestSecurity::enforce();
    try{
        $action=$_POST['action']??'';
        if($action==='client_create'){$createdClient=$oauth->createClient($_POST['name']??'',preg_split('/\R/',trim($_POST['redirects']??'')),$principal['owner'],($_POST['client_type']??'')==='public');$success='اتصال ساخته شد؛ مشخصات محرمانه فقط همین بار نمایش داده می‌شود.';}
        elseif($action==='client_delete'){$store->transaction(static function(&$s)use($principal){$id=$_POST['id']??'';if(($s['clients'][$id]['owner']??'')!==$principal['owner'])throw new RuntimeException('اپ مجاز نیست.');unset($s['clients'][$id]);foreach($s['grants']??[] as $gid=>$g)if($g['client']===$id)$s['grants'][$gid]['revoked']=true;});$success='اپ و تمام اتصال‌های آن لغو شد.';}
        elseif($action==='revoke'){$oauth->revoke($_POST['id']??'',$principal['owner']);$success='دسترسی اتصال لغو شد.';}
