            AiAccess::write();
            if($action==='context'){if(mb_strlen($_POST['context']??'')>6000)throw new RuntimeException('شناخت پروژه حداکثر ۶۰۰۰ نویسه است.');$store->transaction(static function(&$s)use($pid){$s['context'][$pid]=trim($_POST['context']??'');});$success='شناخت پروژه ذخیره شد.';}
            elseif($action==='provider'){$reports->saveProvider($principal,$_POST,array_column($projects,'id'));$success='منبع API و دسترسی‌های اشتراک ذخیره شد.';}
            elseif($action==='schedule'){$reports->schedule($project,$principal,$_POST+['filters'=>array_filter(['from'=>$_POST['from']??'','to'=>$_POST['to']??''])]);$success='برنامهٔ گزارش ذخیره شد.';}
            elseif($action==='disable'){$reports->disable($principal,$_POST['id']??'');$success='برنامه متوقف شد.';}
            elseif($action==='run'){if(session_status()===PHP_SESSION_ACTIVE)session_write_close();$runId=$_POST['run_id']??'';if(!is_string($runId)||!preg_match('/^[a-f0-9]{32}$/D',$runId))throw new RuntimeException('شناسهٔ اجرا معتبر نیست.');$result=$reports->run($_POST['id']??'',$principal,'manual-'.$runId);$success=!empty($result['plan_error'])?$result['plan_error']:(!empty($result['calendar_plan'])?'برنامه در تقویم ثبت و منتظر تأیید است.':'گزارش آماده و ذخیره شد.');}
            elseif($action==='checkout'){if(session_status()===PHP_SESSION_ACTIVE)session_write_close();$url=(new AiBilling($store))->checkout($principal,(int)($_POST['amount']??0));header('Location: '.$url);exit;}
            elseif($action==='resolve'){$reports->resolve($_POST['id']??'',(int)($_POST['charge']??-1));$success='مصرف نامشخص پس از بررسی ثبت شد.';}
            elseif($action==='dataset'){
                $raw=$_POST['dataset_json']??'';if(!is_string($raw)||strlen($raw)>4*1024*1024)throw new RuntimeException('حداکثر ۴ مگابایت داده مجاز است.');$rows=json_decode($raw,true);$data->putDataset($project,$principal,$_POST+['rows'=>$rows]);$success='منبع داده به پروژه اضافه شد.';
            }
            elseif($action==='dataset_delete'){$store->transaction(static function(&$s)use($pid){$id=$_POST['id']??'';$d=$s['datasets'][$id]??null;if(!$d||$d['project']!==$pid)throw new RuntimeException('منبع یافت نشد.');AiAccess::need(AiData::feature($d['kind']),'use');unset($s['datasets'][$id]);});$success='منبع غیرفعال شد؛ گزارش‌های وابسته دیگر در دسترس نیستند.';}
            elseif($action==='content'){$input=$_POST;$file=$_FILES['asset']??null;if($file&&$file['error']===UPLOAD_ERR_OK){if($file['size']>8*1024*1024)throw new RuntimeException('حداکثر ۸ مگابایت تصویر مجاز است.');$input['base64']=base64_encode(file_get_contents($file['tmp_name']));}$input['request_id']=$_POST['request_id']??'';$input['product_id']=$_POST['product_id']??'';$grant=$principal+['scopes'=>['content.write']];$content->save($grant,$input);$success='محتوا در محصول ثبت شد؛ تصاویر اصلی و گالری برای تأیید در پورتال قرار گرفتند.';}
