e="hidden" name="action" value="resolve"><input type="hidden" name="id" value="<?=aiEscape($id)?>"><span><?=aiDate($r['at'])?> · رزرو <?=number_format($r['amount'])?> ریال</span><label>هزینهٔ واقعی به ریال<input name="charge" type="number" min="0" max="<?=(int)$r['amount']?>" required></label><button>ثبت بررسی</button></form><?php endforeach;?></section><?php endif;?>
